import pandas as pd

libros = pd.DataFrame({
    "ref": ["P-01", "P-02", "P-03"],
    "valor": [120000, 80000, 200000],
})
banco = pd.DataFrame({
    "ref": ["P-01", "P-03", "B-09"],
    "valor": [120000, 200000, 15000],
})

cruce = libros.merge(banco, on=["ref", "valor"], how="outer", indicator=True)
cruce["estado"] = cruce["_merge"].astype(str).map({
    "both": "conciliada",
    "left_only": "solo en libros",
    "right_only": "solo en banco",
})
print(cruce[["ref", "valor", "estado"]])
print(cruce.groupby("estado")["valor"].sum())
